window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2e5ea50a527b9b50"]={"versions": [{"id": "FIG-2e5ea50a527b9b50", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Paket- und Header-Layout-Diagramm (Bit-Level-Protokollformat) für das SOME/IP-Protokoll (Scalable service-Oriented MiddlewarE over IP) innerhalb der AUTOSAR-Kommunikationsarchitektur (Classic &amp; Adaptive Platform). Das Diagramm definiert die bitgenaue Struktur eines standardisierten SOME/IP-Nachrichtenheaders über einer 32-Bit-Rasterbreite (Bit Offset 0 bis 31).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format umfasst folgende Header-Felder sowie die Nutzdaten:</p>\n<ul class=\"fig-list\"><li><code>Message ID</code> (32 Bit): Zusammengesetzt aus Service ID und Method ID bzw. Event ID (Bit 0–31).\n</li><li><code>Length</code> (32 Bit): Gibt die Länge in Byte ab der Request ID bis zum Ende der SOME/IP-Nachricht an.\n</li><li><code>Request ID</code> (32 Bit): Zusammengesetzt aus Client ID und Session ID zur Zuordnung von Anfrage und Antwort.\n</li><li><code>Protocol Version</code> (8 Bit): Version des SOME/IP-Header-Formats (Bit 0–7).\n</li><li><code>Interface Version</code> (8 Bit): Hauptversion der Serviceschnittstelle (Bit 8–15).\n</li><li><code>Message Type</code> (8 Bit): Typ der Nachricht (Bit 16–23; z. B. REQUEST, REQUEST_NO_RETURN, NOTIFICATION, RESPONSE, ERROR).\n</li><li><code>Return Code</code> (8 Bit): Status- und Fehlercode (Bit 24–31).\n</li><li><code>Payload</code> (variable Größe): Serialisierte Anwendungsdaten bzw. Parameter.\n</li></ul>\n<p class=\"fig-p\">Rechtsseitige Bereichsindikatoren:</p>\n<ul class=\"fig-list\"><li><code>SOME/IP Header</code>: Umspannt die 16 Byte (128 Bit) von Message ID bis Return Code.\n</li><li><code>Covered by Length</code>: Kennzeichnet den durch das Feld <code>Length</code> abgedeckten Bereich, beginnend ab der Request ID über die verbleibenden Header-Felder bis einschließlich der Payload.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung und Übertragung erfolgt in Big-Endian-Netzwerk-Byte-Reihenfolge (Transmission Order von oben links, Bit 0, nach unten rechts). Im Kommunikationsablauf stellt der Sender den SOME/IP-Header voran; der Empfänger parst anhand der <code>Message ID</code> den Dienst/die Methode, validiert <code>Protocol Version</code> und <code>Interface Version</code>, liest die Restnachrichtengröße über <code>Length</code>, ordnet über die <code>Request ID</code> den Aufruferkontext zu und wertet <code>Message Type</code> sowie <code>Return Code</code> aus, bevor die <code>Payload</code> deserialisiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Header-Layout für sämtliche AUTOSAR-konformen SOME/IP-Implementierungen zur Gewährleistung von Interoperabilität über Steuergeräte- und Plattformgrenzen hinweg. Entwickler müssen beachten:</p>\n<ul class=\"fig-list\"><li>Die Gesamtlänge des SOME/IP-Headers beträgt fix 16 Byte (128 Bit).\n</li><li>Der Wert im Feld <code>Length</code> schließt <code>Message ID</code> und <code>Length</code> selbst nicht ein, sondern deckt exakt 8 Byte Header-Rest (Request ID bis Return Code) zuzüglich der Byte-Länge der Payload ab (<code>Length = 8 + Payload-Länge in Bytes</code>).\n</li><li>Bit-Offsets und Bytereihenfolge müssen exakt eingehalten werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e068b3b2a124cc35", "releases": ["R1.5.1", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Paket- und Header-Layout-Diagramm (Bit-Level-Protokollformat) für das SOME/IP-Protokoll (Scalable service-Oriented MiddlewarE over IP) innerhalb der AUTOSAR-Kommunikationsarchitektur (Classic &amp; Adaptive Platform). Das Diagramm definiert die bitgenaue Struktur eines standardisierten SOME/IP-Nachrichtenheaders über einer 32-Bit-Rasterbreite (Bit Offset 0 bis 31).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Format umfasst folgende Header-Felder sowie die Nutzdaten:</p>\n<ul class=\"fig-list\"><li><code>Message ID</code> (32 Bit): Zusammengesetzt aus Service ID und Method ID bzw. Event ID (Bit 0–31).\n</li><li><code>Length</code> (32 Bit): Gibt die Länge in Byte ab der Request ID bis zum Ende der SOME/IP-Nachricht an.\n</li><li><code>Request ID</code> (32 Bit): Zusammengesetzt aus Client ID und Session ID zur Zuordnung von Anfrage und Antwort.\n</li><li><code>Protocol Version</code> (8 Bit): Version des SOME/IP-Header-Formats (Bit 0–7).\n</li><li><code>Interface Version</code> (8 Bit): Hauptversion der Serviceschnittstelle (Bit 8–15).\n</li><li><code>Message Type</code> (8 Bit): Typ der Nachricht (Bit 16–23; z. B. REQUEST, REQUEST_NO_RETURN, NOTIFICATION, RESPONSE, ERROR).\n</li><li><code>Return Code</code> (8 Bit): Status- und Fehlercode (Bit 24–31).\n</li><li><code>Payload</code> (variable Größe): Serialisierte Anwendungsdaten bzw. Parameter.\n</li></ul>\n<p class=\"fig-p\">Rechtsseitige Bereichsindikatoren:</p>\n<ul class=\"fig-list\"><li><code>SOME/IP Header</code>: Umspannt die 16 Byte (128 Bit) von Message ID bis Return Code.\n</li><li><code>Covered by Length</code>: Kennzeichnet den durch das Feld <code>Length</code> abgedeckten Bereich, beginnend ab der Request ID über die verbleibenden Header-Felder bis einschließlich der Payload.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung und Übertragung erfolgt in Big-Endian-Netzwerk-Byte-Reihenfolge (Transmission Order von oben links, Bit 0, nach unten rechts). Im Kommunikationsablauf stellt der Sender den SOME/IP-Header voran; der Empfänger parst anhand der <code>Message ID</code> den Dienst/die Methode, validiert <code>Protocol Version</code> und <code>Interface Version</code>, liest die Restnachrichtengröße über <code>Length</code>, ordnet über die <code>Request ID</code> den Aufruferkontext zu und wertet <code>Message Type</code> sowie <code>Return Code</code> aus, bevor die <code>Payload</code> deserialisiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Header-Layout für sämtliche AUTOSAR-konformen SOME/IP-Implementierungen zur Gewährleistung von Interoperabilität über Steuergeräte- und Plattformgrenzen hinweg. Entwickler müssen beachten:</p>\n<ul class=\"fig-list\"><li>Die Gesamtlänge des SOME/IP-Headers beträgt fix 16 Byte (128 Bit).\n</li><li>Der Wert im Feld <code>Length</code> schließt <code>Message ID</code> und <code>Length</code> selbst nicht ein, sondern deckt exakt 8 Byte Header-Rest (Request ID bis Return Code) zuzüglich der Byte-Länge der Payload ab (<code>Length = 8 + Payload-Länge in Bytes</code>).\n</li><li>Bit-Offsets und Bytereihenfolge müssen exakt eingehalten werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2e5ea50a527b9b50", "to": "FIG-e068b3b2a124cc35", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e068b3b2a124cc35", "to": "FIG-2e5ea50a527b9b50", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
